        throw FormatException('Invalid ModelMessage tag: ${json["role"]}');
      case "user":
        try { return ModelMessageUser.fromJson(json); } on FormatException { /* Try the next shape. */ }
        throw FormatException('Invalid ModelMessage tag: ${json["role"]}');
      case "assistant":
        try { return ModelMessageAssistant.fromJson(json); } on FormatException { /* Try the next shape. */ }
        throw FormatException('Invalid ModelMessage tag: ${json["role"]}');
      case "tool":
        try { return ModelMessageTool.fromJson(json); } on FormatException { /* Try the next shape. */ }
        throw FormatException('Invalid ModelMessage tag: ${json["role"]}');
      default: throw FormatException('Unknown ModelMessage tag: ${json["role"]}');
    }
  }
  Map<String, dynamic> toJson();
}

